/**
 * R-112 (spec §13 "R-112"): the brand / organisation name (tenants.business_name). The API decides
 * (422 brand_name_invalid / brand_name_blocked); these helpers only label and pre-check, as the app does.
 */
export const BRAND_NAME_MIN = 3
export const BRAND_NAME_MAX = 60

const GENERATED_SUFFIX = "'s Gym Business"

/** The brand as the host typed it; '' for an empty draft or a name generated by app builds up to 25. */
export function typedBrandName(stored?: string | null): string {
  const name = (stored ?? '').trim()
  if (!name || name.endsWith(GENERATED_SUFFIX)) return ''
  return name
}

/**
 * What an admin list or page shows as the tenant's name: the stored brand (admins see old generated
 * names as they are), else the gym name of a draft that has no brand yet.
 */
export function tenantDisplayName(t: { businessName?: string | null; gymName?: string | null }): string {
  return (t.businessName ?? '').trim() || (t.gymName ?? '').trim() || 'No brand yet'
}

/** The gym name under the brand when it adds something. */
export function tenantSubName(t: { businessName?: string | null; gymName?: string | null }): string | null {
  const brand = (t.businessName ?? '').trim()
  const gym = (t.gymName ?? '').trim()
  if (!brand || !gym || gym.toLowerCase() === brand.toLowerCase()) return null
  return gym
}
